patch.css:
/* Rainy Café — ceramic counter and enamel-mug rims.
Shape: containers 16px; nested fields/buttons 10px; tags capsule; native avatars and Conversation bubble silhouettes.
Border: 2px enamel rim on containers, 1px on fields/buttons. Shadow: steam-soft blur only with inset glaze.
Selected: warm fill and inset ring. Focus: inset outline. No control movement or added phone rows.
Home art version 1 is provisional: image viewer did not expose pixels for comparison. */
:root {
 --mari-tokens-version: 1; --radius: 1rem;
 --mari-font-ui: system-ui, sans-serif; --mari-font-heading: Georgia, serif; --mari-font-chat: system-ui, sans-serif; --mari-message-measure: 70ch;
 --mari-selected-tint: var(--primary); --mari-dialogue-color: var(--card-foreground);
 --mari-app-backdrop: url("theme:rainy-window.webp"); --mari-app-backdrop-position: center; --mari-app-backdrop-size: cover;
 --mari-app-backdrop-layers: url("theme:cafe-emblem.webp") right 20px bottom 20px / 72px auto no-repeat, linear-gradient(#241e1a33,#241e1a66), url("theme:rainy-window.webp") center / cover no-repeat;
 --mari-page-veil: var(--background); --mari-top-bar-plate: var(--card); --mari-top-bar-plate-radius: 10px;
 --mari-home-widget-border: var(--border); --mari-home-widget-border-width: 2px; --mari-home-widget-radius: 16px; --mari-home-widget-bg: var(--card);
 --ov-text: var(--foreground); --ov-muted: var(--muted-foreground); --ov-dim: var(--muted-foreground); --ov-line: var(--border); --ov-accent: var(--primary); --ov-hover: var(--accent); --ov-active-bg: var(--secondary);
 --background: #241e1a; --foreground: #f5e9d9; --card: #302721; --card-foreground: #f5e9d9; --popover: #302721; --popover-foreground: #f5e9d9;
 --primary: #edbc7e; --primary-foreground: #2b1c0e; --secondary: #49392d; --secondary-foreground: #f5e9d9; --muted: #3b3028; --muted-foreground: #d0beaa; --accent: #514032; --accent-foreground: #fff1df;
 --border: #7d6855; --input: #8e755e; --ring: #edbc7e; --sidebar: #29221d; --sidebar-foreground: #f5e9d9; --sidebar-border: #7d6855; --sidebar-accent: #49392d; --sidebar-accent-foreground: #fff1df; --destructive: #f5a49a; --destructive-foreground: #381512;
}
[data-theme="light"] {
 --mari-app-backdrop-layers: url("theme:cafe-emblem.webp") right 20px bottom 20px / 72px auto no-repeat, linear-gradient(#f4ebdc22,#f4ebdc44), url("theme:rainy-window.webp") center / cover no-repeat;
 --background: #f4ebdc; --foreground: #35271f; --card: #fff8ed; --card-foreground: #35271f; --popover: #fff8ed; --popover-foreground: #35271f;
 --primary: #854820; --primary-foreground: #fff8ed; --secondary: #ead8bf; --secondary-foreground: #35271f; --muted: #eee1cf; --muted-foreground: #705a47; --accent: #e8d3b6; --accent-foreground: #35271f;
 --border: #ac9072; --input: #9c7b5e; --ring: #854820; --sidebar: #f5e9d7; --sidebar-foreground: #35271f; --sidebar-border: #ac9072; --sidebar-accent: #ead8bf; --sidebar-accent-foreground: #35271f; --destructive: #a43129; --destructive-foreground: #fff8ed;
}
[data-theme="dark"] { color-scheme: dark; }
/* Quiet glaze and sparse grout lines sit on opaque ceramic, not behind text as busy art. */
[data-mari-part="page"], [data-mari-part="home-widget"], .mari-window, .mari-drawer, [data-mari-part="composer"], [data-mari-part="bubble"] {
 background-color: var(--card); color: var(--card-foreground);
 background-image: linear-gradient(135deg, color-mix(in srgb, var(--foreground) 4%, transparent), transparent 48%);
 border: 2px solid var(--border); border-radius: 16px;
 box-shadow: inset 0 0 0 2px var(--card), inset 0 0 0 3px color-mix(in srgb, var(--border) 45%, transparent), 0 8px 24px -14px color-mix(in srgb, var(--foreground) 28%, transparent);
}
[data-mari-part="page"], [data-mari-part="home-widget"] {
 background-image: linear-gradient(color-mix(in srgb, var(--border) 9%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--border) 9%, transparent) 1px, transparent 1px);
 background-size: 64px 64px;
}
[data-mari-part="message"] { background: transparent; border: 0; box-shadow: none; }
/* Conversation retains its existing corner silhouette. */
.texting-bubble[data-mari-part="bubble"] { border-radius: revert-layer; }
[data-mari-part="top-bar"] { background: var(--sidebar); color: var(--sidebar-foreground); border-bottom: 2px solid var(--border); }
.mari-window__header, .mari-drawer__header { background-color: var(--secondary); color: var(--secondary-foreground); border-radius: 12px 12px 8px 8px; border-bottom: 1px solid var(--border); }
:where(button,input,textarea,select) { border-radius: 10px; }
:where(input,textarea,select) { background-color: var(--card); color: var(--foreground); border: 1px solid var(--input); box-shadow: inset 0 2px 5px color-mix(in srgb, var(--border) 12%, transparent); }
:where(input,textarea)::placeholder { color: var(--muted-foreground); opacity: 1; }
:where(button)[aria-pressed="true"], [role="tab"][aria-selected="true"] { background-color: var(--secondary); color: var(--secondary-foreground); box-shadow: inset 0 0 0 2px var(--primary); }
:where(button,input,textarea,select,a):focus-visible { outline: 2px solid var(--ring); outline-offset: -3px; }
/* Public Home-art hook is an img in the current implementation; replace decorative content only. */
[data-mari-part="home-art"] { content: url("theme:cafe-home.webp"); object-fit: cover; object-position: center; border-radius: 14px; }
@media (hover: hover) { [data-mari-part="home-widget"]:hover { border-color: var(--primary); } }
@media (prefers-contrast: more) { [data-mari-part="page"], [data-mari-part="home-widget"] { background-image: none; } }
:root[data-mari-contrast="more"] [data-mari-part="page"], :root[data-mari-contrast="more"] [data-mari-part="home-widget"] { background-image: none; }

